CREATE TYPE "UserRole" AS ENUM ('ADMIN');
CREATE TYPE "ArticleStatus" AS ENUM ('DRAFT','PUBLISHED');
CREATE TYPE "DonationStatus" AS ENUM ('PENDING','CONTACTED','CONFIRMED','RECEIVED','CANCELLED');
CREATE TYPE "ContactRequestStatus" AS ENUM ('PENDING','CONTACTED','RESOLVED','CANCELLED');
CREATE TYPE "ContactRequestType" AS ENUM ('DONATION','FORAGE','FOOD_SUPPORT','VOLUNTEERING','MATERIAL_SUPPORT','GENERAL');
CREATE TABLE "User" ("id" UUID NOT NULL,"email" TEXT NOT NULL,"passwordHash" TEXT NOT NULL,"firstName" TEXT,"lastName" TEXT,"role" "UserRole" NOT NULL DEFAULT 'ADMIN',"isActive" BOOLEAN NOT NULL DEFAULT true,"refreshTokenHash" TEXT,"refreshTokenJti" TEXT,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,"lastLoginAt" TIMESTAMP(3),CONSTRAINT "User_pkey" PRIMARY KEY ("id"));
CREATE TABLE "Category" ("id" UUID NOT NULL,"name" TEXT NOT NULL,"slug" TEXT NOT NULL,"description" TEXT,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "Category_pkey" PRIMARY KEY ("id"));
CREATE TABLE "Article" ("id" UUID NOT NULL,"slug" TEXT NOT NULL,"title" TEXT NOT NULL,"excerpt" TEXT NOT NULL,"content" TEXT NOT NULL,"coverImage" TEXT NOT NULL,"imageAlt" TEXT NOT NULL,"status" "ArticleStatus" NOT NULL DEFAULT 'DRAFT',"isFeatured" BOOLEAN NOT NULL DEFAULT false,"author" TEXT NOT NULL,"readingTimeMinutes" INTEGER NOT NULL DEFAULT 1,"viewsCount" INTEGER NOT NULL DEFAULT 0,"publishedAt" TIMESTAMP(3),"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,"categoryId" UUID NOT NULL,CONSTRAINT "Article_pkey" PRIMARY KEY ("id"));
CREATE TABLE "ArticleView" ("id" UUID NOT NULL,"articleId" UUID NOT NULL,"visitorHash" TEXT NOT NULL,"bucket" TIMESTAMP(3) NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "ArticleView_pkey" PRIMARY KEY ("id"));
CREATE TABLE "Donation" ("id" UUID NOT NULL,"donorName" TEXT NOT NULL,"donorContact" TEXT NOT NULL,"donorEmail" TEXT,"type" TEXT NOT NULL,"amount" DECIMAL(12,2),"currency" TEXT NOT NULL DEFAULT 'XOF',"message" TEXT,"status" "DonationStatus" NOT NULL DEFAULT 'PENDING',"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "Donation_pkey" PRIMARY KEY ("id"));
CREATE TABLE "ContactRequest" ("id" UUID NOT NULL,"name" TEXT NOT NULL,"phone" TEXT NOT NULL,"email" TEXT,"type" "ContactRequestType" NOT NULL DEFAULT 'GENERAL',"message" TEXT,"status" "ContactRequestStatus" NOT NULL DEFAULT 'PENDING',"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "ContactRequest_pkey" PRIMARY KEY ("id"));
CREATE UNIQUE INDEX "User_email_key" ON "User"("email"); CREATE UNIQUE INDEX "Category_name_key" ON "Category"("name"); CREATE UNIQUE INDEX "Category_slug_key" ON "Category"("slug"); CREATE UNIQUE INDEX "Article_slug_key" ON "Article"("slug"); CREATE INDEX "Article_status_publishedAt_idx" ON "Article"("status","publishedAt"); CREATE INDEX "Article_categoryId_idx" ON "Article"("categoryId"); CREATE UNIQUE INDEX "ArticleView_articleId_visitorHash_bucket_key" ON "ArticleView"("articleId","visitorHash","bucket"); CREATE INDEX "ArticleView_createdAt_idx" ON "ArticleView"("createdAt"); CREATE INDEX "Donation_status_createdAt_idx" ON "Donation"("status","createdAt"); CREATE INDEX "Donation_type_idx" ON "Donation"("type"); CREATE INDEX "ContactRequest_status_createdAt_idx" ON "ContactRequest"("status","createdAt"); CREATE INDEX "ContactRequest_type_idx" ON "ContactRequest"("type");
ALTER TABLE "Article" ADD CONSTRAINT "Article_categoryId_fkey" FOREIGN KEY ("categoryId") REFERENCES "Category"("id") ON DELETE RESTRICT ON UPDATE CASCADE;
ALTER TABLE "ArticleView" ADD CONSTRAINT "ArticleView_articleId_fkey" FOREIGN KEY ("articleId") REFERENCES "Article"("id") ON DELETE CASCADE ON UPDATE CASCADE;
